function renderLibrary(){
 const grid=$("bookGrid"); if(!grid) return;
 const q=($("bookSearch").value||"").trim().toLocaleLowerCase();
 const language=$("bookLanguage").value, level=$("bookLevel").value;
 const books=digitalBooks.filter(b=>(language==="all"||b.language===language)&&(level==="all"||b.level===level)&&(`${b.title} ${b.author} ${b.subject} ${b.source}`).toLocaleLowerCase().includes(q));
 grid.innerHTML=books.map(b=>`<article class="book-card"><div class="book-cover ${b.language==='en'?'cover-blue':'cover-gold'}"><span>${b.language==='en'?'EN':'ES'}</span><strong>${escapeHTML(b.title)}</strong><small>${escapeHTML(b.author)}</small></div><div class="book-details"><div class="book-meta"><span>${b.language==='en'?translations[lang].bookEnglish:translations[lang].bookSpanish}</span><span>${translations[lang][b.level==='secondary'?'bookSecondary':'bookPrimary']}</span></div><h3>${escapeHTML(b.title)}</h3><p class="book-author">${escapeHTML(b.author)}</p><p>${escapeHTML(b.note)}</p><small class="book-source">${escapeHTML(b.source)}</small><a class="button button-small book-open-link" href="${b.url}" target="_blank" rel="noopener noreferrer">${translations[lang].bookOpen}</a></div></article>`).join("");
 if(!books.length) grid.innerHTML=`<p class="book-empty">${translations[lang].bookNoResults}</p>`;
}
function openBookReader(book){
 let modal=document.getElementById("bookReaderModal");
 if(!modal){modal=document.createElement("div");modal.id="bookReaderModal";modal.className="book-reader-modal";modal.setAttribute("role","dialog");modal.setAttribute("aria-modal","true");
 modal.innerHTML=`<div class="book-reader-panel"><div class="book-reader-head"><div><strong id="bookReaderTitle"></strong><small id="bookReaderSource"></small></div><button type="button" class="book-reader-close" aria-label="Close reader">✕</button></div><p class="book-reader-help" id="bookReaderHelp"></p><iframe id="bookReaderFrame" title="Book reader" loading="lazy" referrerpolicy="no-referrer"></iframe><div class="book-reader-actions"><a id="bookReaderFallback" target="_blank" rel="noopener noreferrer" class="button button-small">${lang==="es"?"Si no carga, abrir fuente ↗":"If it doesn't load, open source ↗"}</a></div></div>`;document.body.appendChild(modal);
 const close=()=>{modal.classList.remove("is-open");document.body.style.overflow="";document.getElementById("bookReaderFrame").src="about:blank";};modal.querySelector(".book-reader-close").addEventListener("click",close);modal.addEventListener("click",e=>{if(e.target===modal)close();});document.addEventListener("keydown",e=>{if(e.key==="Escape"&&modal.classList.contains("is-open"))close();});}
 document.getElementById("bookReaderTitle").textContent=book.title;document.getElementById("bookReaderSource").textContent=book.author+" · "+book.source;document.getElementById("bookReaderHelp").textContent=lang==="es"?"Intentaremos mostrar el libro aquí mismo. Algunas bibliotecas bloquean la visualización integrada; si ocurre, usa el enlace de respaldo.":"The book will appear here when the source allows embedding. If blocked, use the backup link.";document.getElementById("bookReaderFallback").href=book.url;document.getElementById("bookReaderFrame").src=book.url;modal.classList.add("is-open");document.body.style.overflow="hidden";
}
["bookSearch","bookLanguage","bookLevel"].forEach(id=>$(id)?.addEventListener(id==="bookSearch"?"input":"change",renderLibrary));

